import re
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.wft.interface import wft
from taf.ul.sc.perf.util.logger import (log_debug_function_info, log_function_status_to_console,
                                        log_function_info_to_console, log_info_to_console)


@log_function_info_to_console(msg='Perform BTSs software update', banner=True)
@log_debug_function_info()
def bts_sw_update(sw_version, path_dir_with_builds, stabilization_timer=300):
    desired_sw_version = convert_if_trunk_build(sw_version=sw_version)
    desired_sw_package = get_sw_package_name(sw_version=desired_sw_version)
    bts_to_update = get_bts_to_update(desired_sw_version=desired_sw_version)
    if bts_to_update:
        alarms_before_update = {}
        for bts_instance in bts_to_update:
            sw_package_path = find_package(bts=bts_instance,
                                           path_dir_with_builds=path_dir_with_builds,
                                           sw_package=desired_sw_package)
            if not sw_package_path:
                sw_package_path = download_build_from_wft(bts=bts_instance,
                                                          sw_version=desired_sw_version,
                                                          path_dir_with_builds=path_dir_with_builds,
                                                          sw_package=desired_sw_package)

            alarms_before_update[bts_instance.name] = get_alarms_slogans(bts_instance.get_active_alarms())
            update_status = bts_instance.software_update(sw_package=sw_package_path)
            log_info_to_console(msg=update_status, log_hierarchy=3)
        log_info_to_console(msg='Waiting {}s for BTSs reset and later stabilization.'.format(stabilization_timer),
                            log_hierarchy=3)
        MolerTest.sleep(stabilization_timer)
        for bts_instance in bts_to_update:
            if bts_instance.wait_for_onair():
                status = 'is onAir.'
            else:
                status = 'is not onAir.'

            log_info_to_console(msg='{} {}'.format(bts_instance.name, status), log_hierarchy=3)
        compare_alarms_slogans(bts_to_update=bts_to_update, alarms_before_update=alarms_before_update)
    else:
        log_info_to_console(msg='No BTS to update.', log_hierarchy=3)


@log_function_info_to_console(msg='Find BTSs for software update', log_hierarchy=2)
@log_debug_function_info()
def get_bts_to_update(desired_sw_version):
    bts_to_update = []
    for bts in tc.required_btss():
        if getattr(bts, 'bts', None):
            bts_info = bts.collect_info()
            bts_sw_version = convert_if_trunk_build(bts_info['sw_version'])
            if is_update_needed(actual_sw_version=bts_sw_version, desired_sw_version=desired_sw_version):
                bts_to_update.append(bts)
    return bts_to_update


def convert_if_trunk_build(sw_version):
    trunk_pattern = re.compile(r'(SBTS\d+[a-zA-Z]*\d*)(_ENB_9999_\d+_\d+)')
    if trunk_pattern.match(sw_version):
        sw_version = ('SBTS00{}'.format(trunk_pattern.match(sw_version).group(2)))
    return sw_version


def is_update_needed(actual_sw_version, desired_sw_version):
    if actual_sw_version == desired_sw_version:
        return False
    else:
        return True


def get_sw_package_name(sw_version):
    return '{}_release_BTSSM_downloadable_A54.zip'.format(sw_version)


def find_package(bts, path_dir_with_builds, sw_package):
    result = None
    find_cmd = bts.ws.device.run(cmd_name='find', cmd_params={'paths': [path_dir_with_builds],
                                                              'operators': '-name {}'.format(sw_package)})
    if find_cmd['RESULT']:
        result = find_cmd['RESULT'][0]
    return result


def get_alarms_slogans(alarms):
    alarm_dict = {}
    for alarm in alarms:
        alarm_dict[alarm['faultName']] = alarm['impactedCells']
    return alarm_dict


def compare_alarms_slogans(bts_to_update, alarms_before_update):
    for bts_instance in bts_to_update:
        alarms_after_update = get_alarms_slogans(bts_instance.get_active_alarms())
        if alarms_after_update != alarms_before_update[bts_instance.name]:
            log_info_to_console(msg='Check alarms before and after {} update in test logs.'.format(bts_instance.name),
                                log_hierarchy=3)


@log_function_status_to_console(msg='Downloading build package from WFT', log_hierarchy=3)
@log_debug_function_info()
def download_build_from_wft(bts, sw_version, path_dir_with_builds, sw_package):
    wft_obj = wft()
    wft_obj.download_enb_build_from_wft(build_version=sw_version, destination_path=path_dir_with_builds)
    sw_package_path = find_package(bts=bts,
                                   path_dir_with_builds=path_dir_with_builds,
                                   sw_package=sw_package)
    if not sw_package_path:
        MolerTest.error(msg='Downloading sw package from WFT failed.', raise_exception=True)
    return sw_package_path
